UPDATE marketplace_styles 
SET style_config = jsonb_set(
  style_config,
  '{imageGeneration,prompt_style}',
  '"=== ELLOCONTENT EXCLUSIVE STYLE ===\nCreate an Instagram carousel post in the ELLOCONTENT EXCLUSIVE visual style. This style is defined by REALISTIC DEVICE MOCKUPS showcasing app/website screenshots on dark cinematic backgrounds with bold typography.\n\n=== BACKGROUND ===\nDark gradient background ranging from deep black (#0D0D0D) to deep purple/violet (#2D1B69, #4C1D95). The gradient should be smooth and cinematic, sometimes with subtle purple light flares or glow effects. Never use flat solid colors. The mood is premium, tech-forward, and sophisticated.\n\n=== CORE VISUAL ELEMENT: DEVICE MOCKUPS ===\nEVERY card MUST feature a realistic 3D device mockup as the central visual element:\n- For MOBILE content: Use a photorealistic iPhone mockup (latest model) showing a dark-themed app interface on screen. The phone should be held by a hand, floating at an angle, or placed on a surface. NEVER flat/frontal.\n- For DESKTOP content: Use a photorealistic MacBook/iMac mockup showing a dark-themed web interface.\n- The screen content should show a dark UI with purple accents.\n- Lighting: Dramatic studio lighting with purple/violet rim lights and reflections on the device.\n- VARY the device angle, position, and context across cards.\n- If PRODUCT/SCREENSHOT images are provided as references, you MUST place the EXACT screenshot on the device screen. Do NOT invent a fake UI.\n\n=== TYPOGRAPHY (CRITICAL - MUST MATCH EXACTLY) ===\nFont: Montserrat Black (or equivalent ultra-bold/black weight geometric sans-serif). NEVER use thin, light, regular, or medium weight fonts. The font MUST be extremely heavy and impactful.\n\nTitle style rules:\n1. LARGE, BOLD, WHITE (#FFFFFF) text - minimum visual equivalent of 72pt.\n2. SIGNATURE HIGHLIGHT TECHNIQUE: Select 1-2 key action words and place them inside a solid PURPLE (#8B5CF6) rounded rectangle/pill background. The highlighted text is also white and bold. The pill has generous horizontal padding (about 20-30px equivalent) and subtle rounded corners (8-12px radius).\n3. The remaining title words are white bold WITHOUT any background - just clean white on the dark gradient.\n4. Line spacing is TIGHT - lines should be close together creating a compact, punchy text block.\n5. Text alignment: CENTER aligned.\n6. Example pattern: lanca agora (in purple pill) + dia 20 de Abril! (white, no pill) on separate lines.\n7. ALL text MUST be in PORTUGUES BRASILEIRO.\n\nSecondary text: If present, use Montserrat Medium or Regular, white or light gray (#A0A0A0), significantly smaller than titles (about 40 percent of title size). Clean, minimal.\n\nABSOLUTELY PROHIBITED fonts: Serif fonts, script/handwriting fonts, thin/light weight fonts, decorative fonts, condensed fonts. The typography must feel HEAVY, MODERN, and TECH-FORWARD at all times.\n\n=== LAYOUT ===\nAsymmetric editorial layouts:\n- Title text occupies top 25-35 percent of the card.\n- Device mockup occupies center-bottom 60-70 percent.\n- Text and device may overlap slightly for depth.\n- Generous negative space around elements.\n- Center alignment for text.\n\n=== COLORS (MANDATORY) ===\n#0D0D0D (deep black background), #1A1033 (dark purple), #4C1D95 (medium purple), #8B5CF6 (accent purple for highlights/pills), #FFFFFF (titles and primary text), #A0A0A0 (secondary text)\n\n=== DECORATIVE ===\nSubtle purple light flares, reflections on devices, environmental shadows. NO geometric shapes, NO grid patterns, NO borders/frames. Clean and minimal. The device mockup IS the decoration.\n\n=== PHOTO TREATMENT ===\nHyper-realistic 3D rendering style for devices. Cinematic lighting with purple/violet color cast. High contrast. Professional product photography aesthetic.\n\n=== VARIATION RULES ===\n- Card 1 (COVER): Bold title with purple pill highlight + iPhone or MacBook mockup. Most impactful.\n- Cards 2-4 (CONTENT): Alternate between iPhone and MacBook. Vary angles. Each shows a different screen/feature.\n- Last card (CTA): Minimal layout with typography or device at dramatic angle.\n- NEVER repeat the same device angle across consecutive cards.\n\nRULES: Full bleed. Portugues brasileiro. NAO copie @handles/nomes. O resultado DEVE parecer um post premium de lancamento de produto tech."'::jsonb
)
WHERE id = '391b30f6-204f-49b2-a2ab-a2b114141e96';